svg.script:
var s = Snap('#SVGRoot')

window.onLoad = init;
function init() {

  //
  // Setting labels for applied filters
  // … layer1-18 (lottus SVG filters test icon set)

  for( var i=1; i <= 18; i++ ){
    if(var elem = document.getElementById('layer'+i)){

      elem.onclick( getFilterComponents( elem ));
      elem.onmouseover( function(){

        if( elem.getAttribute('inkscape:label'))
          console.log( elem.getAttribute('inkscape:label'))

        if( elem.getAttribute('inkscape:menu-tooltip'))
          console.log( elem.getAttribute('inkscape:menu-tooltip')) 
      });
     // elem.onmouseout()
    }
  }

  //
  // … layer37-54 (skyline SVG filter elements test)
  //


  //
  //  Generating interface for Inkscape filter in focus

  //  1)  Get container size
  var w = document.getElementById('rect4242').getAttribute('width').baseValue.value,
      h = document.getElementById('rect4242').getAttribute('height').baseValue.value,
      x = document.getElementById('rect4242').getAttribute('x').baseValue.value,
      y = document.getElementById('rect4242').getAttribute('y').baseValue.value,

    /*
      x=65, y=2480, w=1150, h=873.41772, w:h=10,25:7,78481

      4*w + 3*0.75w + 2*1.5w = 1150
      4*h + 3*0.75h + margin-top-bottom = 873.41772

      w=h=2r=112,19512 ; margin-top-bottom=87,34107

    */

  //  2) Define variable scope (necessary to align in place the generated circles)
  var filterCircles = new Array(32),
      i = 0, rowLen = 4,
      r = 56.09756, 
      margin = {
        vertical:  r*3,
        horizontal: 87.34107
      },
      spacing = r*1.5,

      cur: {line: 0, col: 0},
      currentOffset = {x:0, y:0},
   // CuRCGRbMQspuV5nvKqdFpF4Vvafu6PHHlPbdsUTj (hm)

      p = s.path('M10-5-10,15M15,0,0,15M0-5-20,15').attr({
        fill: '#000000',
        stroke: '#bada55',
        strokeWidth: 20
      }),
      p = p.pattern(0, 0, 10, 10);


  filterCircles.forEach(circleItem, function(){ i++;

    if( i/2 % 4){
      currentOffset.x = margin.horizontal,
      currentOffset.y = margin.vertical + currentOffset.y + 2*r
    /*
      cur.line = cur.line + 1
      cur.col = 1 */
    }

    return (i % 2)
   ? Snap.circle(150, 150, 100)
   : Snap.rect(curOffset.x, curOffset.y, r*2, r*2).attr({ fill: p, opacity: 0 });
  });

}

function getFilterComponents() {

  var i=0,
      cur: {line: 0, col: 0},
      currentOffset = {x:0, y:0},
   // CuRCGRbMQspuV5nvKqdFpF4Vvafu6PHHlPbdsUTj

      p = s.path('M10-5-10,15M15,0,0,15M0-5-20,15').attr({
        fill: '#000000',
        stroke: '#bada55',
        strokeWidth: 20
      }),
      p = p.pattern(0, 0, 10, 10);

}

/*
  function getCursorXY(e) {
    var cursor X = (window.Event) ? e.pageX : event.clientX + (document.documentElement.scrollLeft ? document.documentElement.scrollLeft : document.body.scrollLeft),

        cursorY = (window.Event) ? e.pageY : event.clientY + (document.documentElement.scrollTop ? document.documentElement.scrollTop : document.body.scrollTop);
  }

  ...

  let test = document.getElementById('test');

  // This handler will be executed only once when the cursor
  // moves over the unordered list
  test.addEventListener(mouseenter, function( event ) {

  ...

    if (window.Event)
      document.captureEvents(Event.MOUSEMOVE);
    document.onmousemove = getCursorXY
